}

{
  "measurement_needs": [
    "melting temperature",
    "detection of polymorphic phase transitions"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ18",
      "role": "primary",
      "technique": "Differential Scanning Calorimetry (DSC)",
      "why": "DSC measures heat flow associated with phase transitions; it will identify the melting point and can distinguish between polymorphs based on their distinct melting temperatures and enthalpies.",
      "accessories_to_confirm": [
        "Tzero pans and lids",
        "hermetic pans (if the drug is volatile or a hydrate)"
      ]
    },
    {
      "instrument_id": "EQ17",
      "role": "supplementary",
      "technique": "Thermogravimetric Analysis (TGA)",
      "why": "TGA measures mass change versus temperature, which is necessary to confirm that the thermal events observed in DSC are true melting points rather than decomposition or the loss of residual solvents/water.",
      "accessories_to_confirm": [
        "platinum or ceramic sample pans"
      ]
    }
  ],
  "not_available": [
    {
      "technique": "Powder X-ray Diffraction (PXRD)",
      "why_useful": "PXRD is the gold standard for identifying crystalline polymorphs by their unique diffraction patterns, providing structural confirmation that thermal analysis alone cannot."
    },
    {
      "technique": "Hot-stage microscopy",
      "why_useful": "Allows for visual observation of the melting process and any solid-state phase transformations as they occur during heating."
    }
  ],
  "clarifying_question": null,
  "summary": "Differential Scanning Calorimetry (DSC) is the ideal technique to determine melting points and detect the presence of multiple polymorphs. I also recommend using Thermogravimetric Analysis (TGA) to ensure that your sample is thermally stable at the temperatures where melting occurs."
}

